package gameoflife;

import java.util.HashSet;
import java.util.Set;
import java.util.stream.Collectors;

public final class GameOfLife {

    private GameOfLife() {
    }

    public static Set<Cell> nextGeneration(Set<Cell> aliveCells) {
        return candidates(aliveCells).stream()
                .filter(cell -> survives(cell, aliveCells))
                .collect(Collectors.toUnmodifiableSet());
    }

    private static Set<Cell> candidates(Set<Cell> aliveCells) {
        Set<Cell> candidates = new HashSet<>(aliveCells);
        aliveCells.forEach(cell -> candidates.addAll(neighboursOf(cell)));
        return candidates;
    }

    private static boolean survives(Cell cell, Set<Cell> aliveCells) {
        long liveNeighbours = neighboursOf(cell).stream().filter(aliveCells::contains).count();
        return liveNeighbours == 3 || (liveNeighbours == 2 && aliveCells.contains(cell));
    }

    private static Set<Cell> neighboursOf(Cell cell) {
        Set<Cell> neighbours = new HashSet<>();
        for (int dx = -1; dx <= 1; dx++) {
            for (int dy = -1; dy <= 1; dy++) {
                if (dx != 0 || dy != 0) {
                    neighbours.add(new Cell(cell.x() + dx, cell.y() + dy));
                }
            }
        }
        return neighbours;
    }
}
